//#region frontend/groupSwitcher/register.ts
var NODE_TYPE = nodeId("Utils.GroupSwitcher");
var TITLE = "Group Switcher";
var NODE_CATEGORY = `${CATEGORY}/Utils`;
var PACK_ANCHOR = nodeId("Lora.Loader");
app.registerExtension({
	name: `${NAMESPACE}.GroupSwitcher`,
	registerCustomNodes() {
		const { LGraphNode, LiteGraph } = window;
		class GroupSwitcherNode extends LGraphNode {
			static title = TITLE;
			static comfyClass = NODE_TYPE;
			#mounted = false;
			constructor(title) {
				super(title ?? GroupSwitcherNode.title);
				this.isVirtualNode = true;
				this.serialize_widgets = true;
				this.size = [300, 140];
			}
			onAdded() {
				if (this.#mounted) return;
				this.#mounted = true;
				mountWidget(this, {
					widgetName: "switcher",
					widgetType: "NYNXZ_GROUP_SWITCHER",
					component: GroupSwitcher_default,
					defaultValue: { ...DEFAULT_SETTINGS }
				});
			}
		}
		LiteGraph.registerNodeType(NODE_TYPE, GroupSwitcherNode);
		GroupSwitcherNode.category = NODE_CATEGORY;
	},
	beforeRegisterVueAppNodeDefs(defs) {
		const def = defs.find((d) => d.name === NODE_TYPE);
		if (!def) return;
		def.display_name = TITLE;
		def.category = NODE_CATEGORY;
		const sibling = defs.find((d) => d.name === PACK_ANCHOR);
		if (sibling?.python_module) def.python_module = sibling.python_module;
	}
});
